export type ModelOutput = { text: string, tool_calls: Array<ModelToolCall>, continuation: ProviderContinuation, finish_reason: string, actual_model: string | null, usage: Usage, raw_usage: JsonValue | null, };
export type JsonValue = number | string | boolean | Array<JsonValue> | { [key in string]: JsonValue } | null;
export type ExecutionLimits = { max_steps: number, max_duration_ms: number, context_bytes: number, max_result_bytes: number, };
export type ExecutionConfig = { title: string, goal: string, constraints: Array<string>, project_rules: string, project_id: string | null, profile_id: string | null, mode: WorkMode, controlled_tools: boolean, limits: ExecutionLimits, };
export type ModelHistoryItem = { "kind": "message", message: ModelMessage, } | { "kind": "exchange", continuation: ProviderContinuation, tool_results: Array<ModelToolResult>, };
export type PlanStep = { id: string, text: string, status: PlanStepStatus, };
export type PlanStepStatus = "pending" | "running" | "done";
export type InputQuestion = { text: string, choices: Array<string>, plan_confirmation: boolean, };
export type UserDirection = { message_id: string, text: string, steered: boolean, };
export type ContextSource = { step_id: string, summary: string, output: ContentRef, tool_call_ids: Array<string>, };
export type ContextDigest = { compacted_items: number, archive: ContentRef, recent_sources: Array<ContextSource>, };
export type ExecutionContext = { version: number, goal: string, constraints: Array<string>, project_rules: string, directions: Array<UserDirection>, history: Array<ModelHistoryItem>, sources: Array<ContextSource>, digest: ContextDigest | null, plan: Array<PlanStep>, question: InputQuestion | null, pending: PendingBatch | null, last_text: string, };
export type PendingBatch = { model_step_id: string, response: ModelOutput, action_ids: Array<string>, next: number, results: Array<ModelToolResult>, };
export type ExecutionStepKind = "model" | "tool";
export type ExecutionStepState = "prepared" | "running" | "completed" | "failed" | "cancelled" | "skipped" | "needs_review";
export type ExecutionStep = { id: string, run_id: string, ordinal: number, kind: ExecutionStepKind, name: string, state: ExecutionStepState, provider_call_id: string | null, input: ContentRef, output: ContentRef | null, tool_call_id: string | null, started_at_ms: number | null, ended_at_ms: number | null, };
export type ExecutionRun = { run: Run, session_id: string, request_id: string, predecessor_id: string | null, profile: ProviderProfile, mode: WorkMode, limits: ExecutionLimits, steps: number, reason: string | null, diagnostic: ModelDiagnostic | null, };
export type ExecutionSnapshot = { task: Task, session_id: string, agent_id: string, config: ExecutionConfig, latest_run: ExecutionRun | null, checkpoint_id: string | null, context: ExecutionContext, messages: Array<Message>, steps: Array<ExecutionStep>, };
export type ActionResolution = { "kind": "not_applied" } | { "kind": "applied", output: string, };
export type ToolSettings = { root_path: string | null, permission: PermissionMode | null, review_profile_id: string | null, commands_enabled: boolean, revision: number, };
export type DefaultToolSettings = { permission: PermissionMode, review_profile_id: string | null, revision: number, };
export type ToolSettingsView = { settings: ToolSettings, defaults: DefaultToolSettings, effective_permission: PermissionMode, review_profile_id: string | null, epoch: string, root_identity: string | null, };
export type ToolRisk = "read_only" | "managed_write" | "process";
export type ToolDescriptor = { definition: ToolDefinition, result_schema: JsonValue, risk: ToolRisk, scope: string, cancellation: string, replay: string, };
export type FileVersion = { exists: boolean, sha256: string | null, bytes: number, identity: string | null, };
export type ToolIntent = { task_id: string, action_id: string, tool: string, arguments: JsonValue, root_path: string, root_identity: string, target: string, version: FileVersion, epoch: string, mode: WorkMode, risk: ToolRisk, execution_scope: string, };
export type ApprovalReview = { profile_id: string, state: string, reason: string, diagnostic: ModelDiagnostic | null, input: ContentRef | null, output: ContentRef | null, usage: Usage | null, };
export type ToolApproval = { id: string, task_id: string, action_id: string, fingerprint: string, intent: ToolIntent, state: ApprovalState, decided_by: string | null, decided_at_ms: number | null, created_at_ms: number, consumed: boolean, review: ApprovalReview | null, };
export type ManagedFileChange = { action_id: string, path: string, before: FileVersion, after: FileVersion, before_content: ContentRef | null, after_content: ContentRef, };
export type ToolTaskState = { policy: ToolSettingsView, approvals: Array<ToolApproval>, changes: Array<ManagedFileChange>, };
export type TeamSettings = { enabled: boolean, max_parallel: number, max_members: number, max_depth: number, max_replacements: number, revision: number, };
export type WorkspaceAction = { "kind": "save_project", project_id: string | null, settings: ProjectSettings, } | { "kind": "archive_task", task_id: string, archived: boolean, } | { "kind": "rename_task", task_id: string, title: string, } | { "kind": "edit_message", task_id: string, message_id: string, expected_object_id: string, text: string, } | { "kind": "cancel_message", task_id: string, message_id: string, expected_object_id: string, } | { "kind": "save_preferences", preferences: WorkspacePreferences, } | { "kind": "export_records", task_id: string, };
export type WorkspaceQuery = { "kind": "overview" } | { "kind": "tasks", project_id: string | null, archived: boolean, search: string, before: string | null, limit: number, } | { "kind": "detail", task_id: string, } | { "kind": "conversation", task_id: string, before: number | null, limit: number, } | { "kind": "artifacts", task_id: string, } | { "kind": "search_records", task_id: string, text: string, after: number, limit: number, };
export type WorkspaceData = { "kind": "overview", projects: Array<WorkspaceProject>, preferences: WorkspacePreferences, scheduler: SchedulerSettings, data_dir: string, notices: Array<WorkspaceNotice>, } | { "kind": "project_saved", project: WorkspaceProject, } | { "kind": "tasks", tasks: Array<Task>, next_before: string | null, } | { "kind": "detail", snapshot: ExecutionSnapshot, archived: boolean, effective_profile: ProviderProfile | null, effective_permission: PermissionMode, live_text: string, live_reasoning: string, } | { "kind": "conversation", entries: Array<ConversationEntry>, next_before: number | null, } | { "kind": "artifacts", artifacts: Array<WorkspaceArtifact>, } | { "kind": "search_records", events: Array<Event>, next_after: number, has_more: boolean, } | { "kind": "exported", path: string, events: number, objects: number, } | { "kind": "updated" };
export type WorkspacePreferences = { language: string, theme: string, sidebar_width: number, inspector_width: number, sidebar_closed: boolean, inspector_closed: boolean, revision: number, };
export type ProjectSettings = { name: string, root_path: string, default_profile_id: string | null, permission: PermissionMode, rules: string, revision: number, };
export type WorkspaceProject = { id: string, settings: ProjectSettings, created_at_ms: number, };
export type WorkspaceNotice = { task_id: string, root_task_id: string, title: string, state: TaskState, };
export type WorkspaceArtifact = { id: string, task_id: string, title: string, path: string, revision_id: string, content: ContentRef, };
export type ConversationEntry = { sequence: number, role: string, at_ms: number, text: string, truncated: boolean, source: ContentRef, };
export type SchedulerSettings = { max_running: number, revision: number, };
export type MemberSpec = { key: string, role: string, goal: string, profile_id: string | null, depends_on: Array<string>, };
export type TeamMember = { task_id: string, agent_id: string, parent_task_id: string, root_task_id: string, key: string, role: string, goal: string, profile_id: string, depth: number, replaces_id: string | null, superseded_by: string | null, replacement_reason: string | null, attempt: number, state: TaskState, pending_start: boolean, depends_on: Array<string>, report: ContentRef | null, review: string, review_reason: string | null, diagnostic: ModelDiagnostic | null, };
export type TeamView = { root_task_id: string, settings: TeamSettings, scheduler: SchedulerSettings, scheduling_enabled: boolean, members: Array<TeamMember>, };
export type AgentArtifact = { path: string, revision_id: string, content: ContentRef, };
export type AgentReport = { task_id: string, agent_id: string, run_id: string | null, state: TaskState, summary: string, summary_truncated: boolean, result: ContentRef | null, artifacts: Array<AgentArtifact>, steps: Array<ExecutionStep>, usage: Usage, diagnostic: ModelDiagnostic | null, };
export type MediaAdmin = { "kind": "begin_upload", name: string, bytes: number, source: string, } | { "kind": "upload_chunk", upload_id: string, offset: number, base64: string, } | { "kind": "finish_upload", upload_id: string, } | { "kind": "cancel_upload", upload_id: string, } | { "kind": "bind", asset_ids: Array<string>, } | { "kind": "list" } | { "kind": "read", asset_id: string, start: number, limit: number, } | { "kind": "preview", asset_id: string, page: number, } | { "kind": "cancel_preview", asset_id: string, } | { "kind": "remove", asset_id: string, } | { "kind": "image_services" } | { "kind": "save_image_service", service: ImageService, secret: string | null, } | { "kind": "remove_image_service", service_id: string, };
export type MediaAsset = { id: string, task_id: string | null, name: string, source: string, media_type: string, bytes: number, sha256: string, at_ms: number, units: number, warnings: Array<string>, image: ImageDimensions | null, path: string | null, version: FileVersion | null, operation_id: string | null, };
export type DocumentUnit = { locator: string, text: string, };
export type ImageService = { id: string, label: string, base_url: string, model: string, revision: number, credential: CredentialRef | null, supports_edit: boolean, sizes: Array<string>, qualities: Array<string>, formats: Array<string>, max_count: number, request_base64: boolean, auth_required: boolean, };
export type ImageRequest = { service_id: string, service_revision: number, prompt: string, size: string, quality: string | null, format: string, count: number, references: Array<string>, paths: Array<string>, expected: Array<FileVersion>, };
export type MediaEffect = { "kind": "create_document", path: string, expected: FileVersion, format: string, recipe: JsonValue, } | { "kind": "generate_image", request: ImageRequest, };
export type ImageDimensions = { width: number, height: number, };
